+      tags: [],
+      id: i,
+      kids: [
+        { tags: [], id: i, kids: [node] },
+        { tags: [], id: i, kids: [node] },
+      ],
+    };
+  expect(Node.safeParse(node).error!.issues.length).toBe(151);
+});
